package ru.arc.helpcenter

import ru.arc.config.Config
import ru.arc.config.ConfigManager
import java.nio.file.Path

data class HelpCenterCommandText(
    val label: String,
    val description: String,
    val keywords: String,
)

data class HelpCenterIntentText(
    val label: String,
    val description: String,
    val keywords: String,
)

data class HelpCenterSettings(
    val enabled: Boolean,
    val maxHomes: Int,
    val maxSearchResults: Int,
    val loadTimeoutSeconds: Long,
    private val text: Map<String, String>,
    private val commands: Map<String, HelpCenterCommandText>,
    private val intents: Map<String, HelpCenterIntentText>,
) {
    fun text(key: String): String = text.getValue(key)

    fun command(id: String): HelpCenterCommandText = commands.getValue(id)

    fun intent(id: String): HelpCenterIntentText = intents.getValue(id)
}

class HelpCenterConfig(private val config: Config) {
    fun snapshot(): HelpCenterSettings {
        val maxHomes = config.integer("limits.max-homes", 12)
        val maxSearchResults = config.integer("limits.max-search-results", 8)
        val loadTimeoutSeconds = config.long("limits.load-timeout-seconds", 3)
        require(maxHomes in 1..32) { "Help center max-homes must be in 1..32" }
        require(maxSearchResults in 1..32) { "Help center max-search-results must be in 1..32" }
        require(loadTimeoutSeconds in 1..10) { "Help center load-timeout-seconds must be in 1..10" }
        return HelpCenterSettings(
            enabled = config.bool("enabled", true),
            maxHomes = maxHomes,
            maxSearchResults = maxSearchResults,
            loadTimeoutSeconds = loadTimeoutSeconds,
            text = DEFAULT_TEXT.mapValues { (key, fallback) -> required("text.$key", fallback) },
            commands = COMMANDS.mapValues { (id, fallback) ->
                HelpCenterCommandText(
                    label = required("commands.$id.label", fallback.label),
                    description = required("commands.$id.description", fallback.description),
                    keywords = required("commands.$id.keywords", fallback.keywords),
                )
            },
            intents = INTENTS.mapValues { (id, fallback) ->
                HelpCenterIntentText(
                    label = required("intents.$id.label", fallback.label),
                    description = required("intents.$id.description", fallback.description),
                    keywords = required("intents.$id.keywords", fallback.keywords),
                )
            },
        )
    }

    private fun required(path: String, fallback: String): String = config.string(path, fallback).also { value ->
        require(value.isNotBlank()) { "Help center value '$path' cannot be blank" }
        require(value.length <= 2_000) { "Help center value '$path' is too long" }
    }

    companion object {
        private const val RESOURCE = "help-center.yml"

        fun load(dataPath: Path): HelpCenterConfig {
            val source = ConfigManager.ofModule(dataPath, RESOURCE)
            source.mergeMissingFromBundled("modules/$RESOURCE")
            return HelpCenterConfig(source)
        }

        private val DEFAULT_TEXT = linkedMapOf(
            "dungeons-title" to "<#86dcf1>Данжи",
            "dungeons-body" to "<#e8dfd2>В данжах вас ждут элитные противники, боссы, задания и особое снаряжение.<newline><newline><#9bd48d>Порталы <#e8dfd2>— перейти в Гильдию искателей приключений.<newline><#f4bd6a>Гайд <#e8dfd2>— разобраться в подготовке и прохождении.<newline><#86dcf1>Меню /em <#e8dfd2>— открыть журнал EliteMobs.",
            "dungeons-portals-label" to "<#9bd48d>› Порталы",
            "dungeons-portals-tooltip" to "<#9bd48d>Куда попадёте<newline><#e8dfd2>В Гильдию искателей приключений: к порталам и специалистам по снаряжению.<newline><newline><#f4bd6a>Что сделать там<newline><#e8dfd2>Выберите данж по уровню, прочитайте условия и подготовьтесь к бою.<newline><#c9c3ba>Нажатие закроет меню и выполнит /pw aguild. Если рядом появился портал — войдите в него; в режиме прямой телепортации перенос начнётся автоматически.",
            "dungeons-guide-label" to "<#f4bd6a>◇ Гайд",
            "dungeons-guide-tooltip" to "<#e6fff3>Подробно о входе, группах, навыках, наградах и командах.<newline><#c9c3ba>Сначала выберите подходящий раздел для новичка.",
            "dungeons-menu-label" to "<#86dcf1>Меню /em",
            "dungeons-menu-tooltip" to "<#86dcf1>Журнал EliteMobs<newline><#e8dfd2>Открывает родное меню: снаряжение, навыки, задания и доступные входы.<newline><newline><#c9c3ba>С выживания к основным данжам сначала перейдите через «Порталы». Подробные объяснения и команды собраны в гайде рядом.",
            "dungeons-guide-title" to "<#f4bd6a>Гайд по данжам",
            "dungeons-guide-body" to "<#e8dfd2>Этот гайд объясняет прохождения на сервере спавна. С выживания сначала перейдите туда кнопкой «Порталы».<newline><newline><#e8dfd2>Новичку пригодятся «С чего начать», «Снаряжение» и «Бой». Для похода с друзьями — «Группа», после победы — награды и улучшения.<newline><#c9c3ba>В каждой главе: порядок действий, механики и команды.",
            "dungeons-guide-start-label" to "<#d7b486>С чего начать",
            "dungeons-guide-start-tooltip" to "<#e6fff3>Первые шаги для входа в данж.<newline><#c9c3ba>Откройте раздел, чтобы увидеть порядок действий и команды.",
            "dungeons-guide-start-intro" to "<#f4bd6a>Первый поход<newline><#e8dfd2>1. Нажмите «Порталы» или введите /pw aguild. Если рядом появился портал — войдите в него: он ведёт в Гильдию. В режиме прямой телепортации перенос начнётся автоматически.<newline>2. Найдите вход с посильным уровнем. Прочитайте описание: сложность, условия и размер группы.<newline>3. Возьмите броню, оружие, еду и лечение; оставьте место для добычи. Начните с обычной сложности.<newline>4. Подтвердите вход. Если открылось лобби, дождитесь товарищей и запуска прохождения.",
            "dungeons-guide-start-mechanics" to "<#f4bd6a>Если не получается войти<newline><#e8dfd2>Проверьте требования самого входа: уровень, доступ и готовность группы. Открытый данж и отдельное прохождение запускаются по-разному.<newline>После похода осмотрите добычу, сдайте задания и почините экипировку. Затем выбирайте следующий маршрут — усложнять первый заход не обязательно.",
            "dungeons-guide-start-commands" to "<#f4bd6a>Команды<newline><#9bd48d>/pw aguild <#e8dfd2>— к порталам<newline><#9bd48d>/em <#e8dfd2>— журнал и выбор разделов<newline><#9bd48d>/em start <#e8dfd2>— начать подготовленное прохождение<newline><#9bd48d>/em quit <#e8dfd2>— выйти из отдельного прохождения",
            "dungeons-guide-equipment-label" to "<#d7b486>Снаряжение",
            "dungeons-guide-equipment-tooltip" to "<#e6fff3>Как подготовить экипировку.<newline><#c9c3ba>Откройте раздел, чтобы увидеть порядок действий и команды.",
            "dungeons-guide-equipment-intro" to "<#f4bd6a>Что взять с собой<newline><#e8dfd2>Прочное оружие, полный комплект брони, еду и лечение. Для дальнего боя проверьте боезапас; оставьте свободные ячейки для трофеев.<newline>У элитных вещей читайте уровень и особые свойства в описании. Сравнивайте весь набор, а не только материал: алмазный предмет не обязательно лучше подходящей элитной вещи.",
            "dungeons-guide-equipment-mechanics" to "<#f4bd6a>Уровень и привязка<newline><#e8dfd2>Элитное снаряжение проверяет соответствующий навык: оружие — свой тип, броня — навык брони. У вещей выше 20-го уровня действует ограничение по навыку: слишком сильную находку сначала отложите.<newline>Привязка к владельцу защищает добычу: чужой игрок не сможет просто подобрать и использовать её. Это отдельное свойство, которое не исчезает от ремонта. Перед обменом проверьте владельца в описании.",
            "dungeons-guide-equipment-commands" to "<#f4bd6a>Команды<newline><#9bd48d>/em repair <#e8dfd2>— ремонт у специалиста<newline><#9bd48d>/em unbind <#e8dfd2>— снятие привязки<newline><#9bd48d>/em <#e8dfd2>— ваше снаряжение и навыки",
            "dungeons-guide-combat-label" to "<#d7b486>Бой",
            "dungeons-guide-combat-tooltip" to "<#e6fff3>Как работает бой с элитным мобом.<newline><#c9c3ba>Откройте раздел, чтобы увидеть порядок действий и команды.",
            "dungeons-guide-combat-intro" to "<#f4bd6a>Как сражаться<newline><#e8dfd2>Следите за уровнем и именем противника. Элитные мобы и боссы используют особые атаки: замечайте предупреждения, эффекты на земле, снаряды и призванных помощников.<newline>Не стойте в опасной зоне ради ещё одного удара. Держите лечение под рукой, оставляйте путь для отхода. В группе заранее договоритесь, кто отвлекает босса и кто разбирается с помощниками.",
            "dungeons-guide-combat-mechanics" to "<#f4bd6a>Поражение и повторная попытка<newline><#e8dfd2>У отдельных прохождений свои условия смерти и оставшихся попыток. После исчерпания попыток можно оказаться наблюдателем: следите за сообщениями данжа и действиями группы.<newline>Не обещайте себе мгновенное возвращение в бой: возможность продолжить зависит от маршрута. Если нужно выйти, используйте команду ниже, затем восстановите запасы и пересмотрите сложность.",
            "dungeons-guide-combat-commands" to "<#f4bd6a>Команды<newline><#9bd48d>/em quit <#e8dfd2>— покинуть отдельное прохождение<newline><#9bd48d>/pw aguild <#e8dfd2>— вернуться к подготовке в Гильдии",
            "dungeons-guide-dungeons-label" to "<#d7b486>Типы данжей",
            "dungeons-guide-dungeons-tooltip" to "<#e6fff3>Чем отличаются форматы данжей.<newline><#c9c3ba>Откройте раздел, чтобы увидеть порядок действий и команды.",
            "dungeons-guide-dungeons-intro" to "<#f4bd6a>Выберите подходящий формат<newline><#e8dfd2>Открытый данж — общий мир: рядом могут быть другие игроки, а противники появляются повторно.<newline>Отдельное прохождение — отдельная копия локации для участников, со своим началом и завершением.<newline>Динамический данж — вариант отдельного прохождения с выбором уровня или сложности. Перед подтверждением посмотрите, что именно выбрано.",
            "dungeons-guide-dungeons-mechanics" to "<#f4bd6a>Что означает название<newline><#e8dfd2>Логово и святилище обычно сосредоточены на боссе. Подземелье ведёт по маршруту через обычных противников и промежуточные бои. Приключение объединяет исследование и цепочку заданий, арена — последовательные волны.<newline>ID — служебное имя конкретного данжа или арены. Если его не знаете, выбирайте вход через портал или /em; русское название вместо ID может не подойти.",
            "dungeons-guide-dungeons-commands" to "<#f4bd6a>Команды<newline><#9bd48d>/em <#e8dfd2>— выбрать вход через меню<newline><#9bd48d>/em dungeontp ID <#e8dfd2>— перейти к известному данжу<newline><#9bd48d>/em arena ID <#e8dfd2>— войти на указанную арену",
            "dungeons-guide-rewards-label" to "<#d7b486>Награды и валюта",
            "dungeons-guide-rewards-tooltip" to "<#e6fff3>Что делать с добычей.<newline><#c9c3ba>Откройте раздел, чтобы увидеть порядок действий и команды.",
            "dungeons-guide-rewards-intro" to "<#f4bd6a>Разберите добычу после боя<newline><#e8dfd2>Сначала сравните найденные вещи с надетыми: уровень, свойства, прочность и привязку. Полезные оставьте; ненужные можно продать или разобрать на материалы для ремонта.<newline>Проверьте задания: победа над боссом может выполнить цель, но за самой наградой ещё потребуется вернуться к NPC. Условия конкретного данжа важнее обещания одинаковой награды за любой бой.",
            "dungeons-guide-rewards-mechanics" to "<#f4bd6a>Кристаллы и покупки<newline><#e8dfd2>В EliteMobs используется отдельная валюта — кристаллы. Это баланс для магазинов и услуг Гильдии; проверяйте его командой ниже.<newline>Перед покупкой, зачарованием или снятием привязки прочитайте цену и условия. При переводе другому игроку учитывается налог: полученная сумма может отличаться от отправленной. НИК и СУММА в примере заменяются именем игрока и числом.",
            "dungeons-guide-rewards-commands" to "<#f4bd6a>Команды<newline><#9bd48d>/em money check <#e8dfd2>— баланс кристаллов<newline><#9bd48d>/em shop dynamic <#e8dfd2>— магазин с меняющимся ассортиментом<newline><#9bd48d>/em shop custom <#e8dfd2>— магазин особых предметов<newline><#9bd48d>/em pay НИК СУММА <#e8dfd2>— перевести кристаллы",
            "dungeons-guide-guild-label" to "<#d7b486>Гильдия и навыки",
            "dungeons-guide-guild-tooltip" to "<#e6fff3>Что есть в гильдейском хабе.<newline><#c9c3ba>Откройте раздел, чтобы увидеть порядок действий и команды.",
            "dungeons-guide-guild-intro" to "<#f4bd6a>Где искать помощь<newline><#e8dfd2>Гильдия искателей приключений — место подготовки между походами. Здесь находятся порталы, выдающие задания NPC, магазины и специалисты по предметам.<newline>Разборщик перерабатывает ненужную добычу, Ремонтник восстанавливает прочность, Зачарователь улучшает зачарования. За свитками, снятием привязки и бонусами навыков обращайтесь к соответствующим специалистам.",
            "dungeons-guide-guild-mechanics" to "<#f4bd6a>Навыки и бонусы<newline><#e8dfd2>Развиваются девять навыков: броня, мечи, топоры, луки, арбалеты, трезубцы, мотыги, булавы и копья. Побеждайте элитных мобов оружием нужного типа; броня растёт медленнее.<newline>На уровнях 10, 25, 50 и 75 открываются ступени бонусов. Для одного типа навыка можно выбрать до трёх активных бонусов. Проверяйте новые варианты после повышения уровня — открытый бонус ещё нужно выбрать.",
            "dungeons-guide-guild-commands" to "<#f4bd6a>Команды<newline><#9bd48d>/pw aguild <#e8dfd2>— в Гильдию<newline><#9bd48d>/em <#e8dfd2>— навыки и доступные разделы",
            "dungeons-guide-crafting-label" to "<#d7b486>Предметы и улучшения",
            "dungeons-guide-crafting-tooltip" to "<#e6fff3>Как обслуживать добычу.<newline><#c9c3ba>Откройте раздел, чтобы увидеть порядок действий и команды.",
            "dungeons-guide-crafting-intro" to "<#f4bd6a>Ремонт и разбор<newline><#e8dfd2>Ненужный элитный предмет отдайте Разборщику: при успешном разборе получите материалы. Действие расходует исходную вещь — сначала проверьте, что выбрали.<newline>Материалы используются у Ремонтника для восстановления прочности. Ремонт не повышает уровень, не добавляет зачарования и не снимает привязку.",
            "dungeons-guide-crafting-mechanics" to "<#f4bd6a>Зачарования, свитки и привязка<newline><#e8dfd2>Зачарователь работает с элитной вещью и книгой зачарования. Попытка стоит кристаллы, цена зависит от уже имеющихся зачарований, а успех не гарантирован; талон удачи может помочь.<newline>Свиток придаёт обычной вещи элитный уровень через специалиста по свиткам. Снятие привязки позволяет освободить вещь от владельца на условиях отдельной услуги. Перед любой операцией прочитайте стоимость и предупреждение в её меню.",
            "dungeons-guide-crafting-commands" to "<#f4bd6a>Команды<newline><#9bd48d>/em repair <#e8dfd2>— ремонт<newline><#9bd48d>/em scrap <#e8dfd2>— разбор<newline><#9bd48d>/em enchant <#e8dfd2>— зачарование<newline><#9bd48d>/em scroll <#e8dfd2>— применение свитка<newline><#9bd48d>/em unbind <#e8dfd2>— снятие привязки",
            "dungeons-guide-quests-label" to "<#d7b486>Квесты",
            "dungeons-guide-quests-tooltip" to "<#e6fff3>Как брать и отслеживать квесты.<newline><#c9c3ba>Откройте раздел, чтобы увидеть порядок действий и команды.",
            "dungeons-guide-quests-intro" to "<#f4bd6a>От принятия до награды<newline><#e8dfd2>1. Поговорите с выдающим задания NPC и прочитайте цель: кого победить, куда сходить или что принести.<newline>2. Примите задание. Отслеживание включается автоматически; следите за счётчиком прогресса.<newline>3. После выполнения цели вернитесь к указанному NPC и сдайте задание. Заполненный счётчик ещё не означает, что награда получена.",
            "dungeons-guide-quests-mechanics" to "<#f4bd6a>Почему задание недоступно<newline><#e8dfd2>Одновременно можно вести до 10 заданий. Следующее может открыться только после предыдущего, требовать нужного NPC или ожидания повторного прохождения.<newline>Если места не хватает, завершите текущие задания либо откажитесь от ненужного. ID в командах — идентификатор задания: используйте его только если он известен; для первого раза удобнее диалог с NPC.",
            "dungeons-guide-quests-commands" to "<#f4bd6a>Команды<newline><#9bd48d>/em quest accept ID <#e8dfd2>— принять<newline><#9bd48d>/em quest track ID <#e8dfd2>— отслеживать<newline><#9bd48d>/em quest complete ID <#e8dfd2>— сдать выполненное<newline><#9bd48d>/em quest leave ID <#e8dfd2>— отказаться",
            "dungeons-guide-groups-label" to "<#d7b486>Группа",
            "dungeons-guide-groups-tooltip" to "<#e6fff3>Как пройти вместе.<newline><#c9c3ba>Откройте раздел, чтобы увидеть порядок действий и команды.",
            "dungeons-guide-groups-intro" to "<#f4bd6a>Соберите группу<newline><#e8dfd2>Сначала перейдите к порталам на сервере спавна: команды группы доступны там.<newline>Лидер создаёт группу и приглашает товарищей по никам. Каждый участник принимает приглашение; перед входом проверьте состав через меню группы.<newline>Заранее договоритесь о данже и сложности. Почините броню, пополните еду и освободите инвентарь до подтверждения готовности — остальные не должны ждать, пока вы закончите подготовку.",
            "dungeons-guide-groups-mechanics" to "<#f4bd6a>Совместный вход<newline><#e8dfd2>Лидер выбирает конкретный данж, остальные подтверждают тот же маршрут и сложность. Если кто-то отказался, не ответил вовремя или состав изменился, соберите готовых участников и повторите выбор.<newline>Во время похода держитесь рядом для общего прогресса заданий. Не уходите из группы случайно: выход меняет состав, а уже начатое прохождение имеет собственные правила. Приглашение в группу и вход в данж — два разных шага.",
            "dungeons-guide-groups-commands" to "<#f4bd6a>Команды<newline><#9bd48d>/em party create <#e8dfd2>— создать группу<newline><#9bd48d>/em party invite НИК <#e8dfd2>— пригласить<newline><#9bd48d>/em party accept <#e8dfd2>— принять приглашение<newline><#9bd48d>/em party menu <#e8dfd2>— состав и управление<newline><#9bd48d>/em party leave <#e8dfd2>— выйти из группы",
            "dungeons-guide-commands-label" to "<#d7b486>Команды",
            "dungeons-guide-commands-tooltip" to "<#e6fff3>Короткая памятка.<newline><#c9c3ba>Откройте раздел, чтобы увидеть порядок действий и команды.",
            "dungeons-guide-commands-intro" to "<#f4bd6a>Первые команды<newline><#e8dfd2>Для начала достаточно /pw aguild и /em: первая ведёт к порталам Гильдии, вторая открывает журнал. Через них можно выбрать маршрут без знания его ID.<newline>Войдя в отдельное прохождение, прочитайте подсказку о старте. /em start начинает подготовленный заход, а /em quit нужен для раннего выхода. Обычный открытый данж не требует такого запуска.",
            "dungeons-guide-commands-mechanics" to "<#f4bd6a>Как читать примеры<newline><#e8dfd2>НИК замените точным именем игрока, СУММА — числом, ID — идентификатором данжа, арены или задания. Слова-заготовки вводить буквально не нужно.<newline>Команды группы собраны в разделе «Группа», операции с добычей — в «Предметы и улучшения». Если привычный вид журнала неудобен, /em alt переключает его оформление; после этого снова откройте /em.",
            "dungeons-guide-commands-commands" to "<#f4bd6a>Команды<newline><#9bd48d>/pw aguild <#e8dfd2>— порталы и Гильдия<newline><#9bd48d>/em <#e8dfd2>— журнал EliteMobs<newline><#9bd48d>/em start <#e8dfd2>— старт прохождения<newline><#9bd48d>/em quit <#e8dfd2>— выход из прохождения<newline><#9bd48d>/em alt <#e8dfd2>— другой вид журнала",
            "menu-close-label" to "<#aaa49a>Закрыть меню",
            "settings-flight-back-label" to "<#aaa49a>‹ Назад",
            "settings-flight-auto-off-help" to "<#e8dfd2>Отключение сохранит накопленный заряд.<newline><#aaa49a>Режим полёта включается на предыдущем экране.",
            "settings-flight-auto-current" to "<#aaa49a>Настройки / Полёт / Автопополнение<newline><#e8dfd2>Выбран способ: <state>",
            "settings-flight-auto-label" to "<#d7b486>Автопополнение: <state><#d7b486> ›",
            "settings-flight-unavailable" to "<#aaa49a>Запас заряда и состояние полёта недоступны.<newline>Откройте раздел позже, чтобы обновить данные.",
            "settings-flight-status" to "<#e4b878>Запас заряда<newline><#9bd48d><filled><#aaa49a><empty>  <#e8dfd2><percent>%<newline><#e8dfd2><charge> / <maximum><#aaa49a>    Полёт: <state>",
            "settings-flight-unavailable-label" to "<#aaa49a>Полёт: неизвестно",
            "settings-flight-disable-label" to "<#d7b486>Выключить полёт",
            "settings-flight-enable-label" to "<italic:false><#9bd48d>Включить полёт",
            "settings-flight-how" to "<italic:false><#e8dfd2>Заряд расходуется при движении в воздухе и зависании.<newline>Для взлёта включите полёт и дважды нажмите прыжок.<newline><#aaa49a>Нужны доступ к полёту и оставшийся заряд.",
            "settings-flight-breadcrumb" to "<italic:false><#aaa49a>Настройки / Мир и перемещение / Полёт",
            "settings-flight-title" to "<italic:false><#f4bd6a>Полёт и подзарядка",
            "settings-portal-style-option-tooltip" to "<#e8dfd2>Оформление: <state><newline><newline><#d7b486>Нажмите, чтобы выбрать этот вид портала.",
            "settings-options-flight-body" to "<#e8dfd2>Выберите ресурс для автоматической покупки заряда.",
            "settings-options-flight-title" to "<#f4bd6a>Автопополнение заряда",
            "settings-options-portal-style-body" to "<#e8dfd2>Выберите оформление создаваемого портала.<newline>Галочка отмечает текущий стиль.",
            "settings-options-portal-style-title" to "<#86dcf1>Вид портала",
            "settings-options-lands-body" to "<#e8dfd2>Покажите границы территории рядом с собой<newline>или отключите их подсветку.",
            "settings-options-lands-title" to "<#9bd48d>Границы земель",
            "settings-options-tablist-body" to "<#e8dfd2>Выберите оформление списка игроков по клавише Tab.<newline>«Выключить» уберёт дополнительное оформление.",
            "settings-options-tablist-title" to "<#86dcf1>Список игроков",
            "settings-options-scoreboard-body" to "<#e8dfd2>Выберите набор информации справа на экране.<newline>«Выключить» полностью скроет панель.",
            "settings-options-scoreboard-title" to "<#86dcf1>Информационная панель",
            "settings-options-escape-body" to "<#e8dfd2>Закрыть — выйти из всех меню.<newline>Назад — вернуться к предыдущему экрану.",
            "settings-options-escape-title" to "<#f3a2c9>Поведение Escape",
            "settings-options-shortcut-body" to "<#e8dfd2>Выберите действие для сочетания Shift + F.<newline>Обычная клавиша F продолжит менять предметы в руках.",
            "settings-options-shortcut-title" to "<#f3a2c9>Горячая клавиша Shift + F",
            "settings-options-body" to "<#aaa49a>Сейчас: <#e8dfd2><state>",
            "settings-selected-option" to "<#9bd48d>✔ <label>",
            "settings-trails-unavailable-tooltip" to "<#e8dfd2>Состояние тропинок на этом сервере недоступно.<newline><#aaa49a>Кнопка не меняет настройки.<newline>Попробуйте открыть раздел позже или на другом сервере.",
            "settings-unavailable-state" to "<#aaa49a>недоступно",
            "settings-back-label" to "<#aaa49a>‹ Назад",
            "settings-hub-body" to "<#e8dfd2>Настройте игру под себя.<newline><#aaa49a>Shift + F: <#e8dfd2><shortcut><#aaa49a>    Escape: <#e8dfd2><escape>",
            "settings-world-tooltip" to "<italic:false><#e8dfd2>Тропинки, границы земель и полёт.<newline>Доступ к порталам и их оформление.",
            "settings-world-label" to "<italic:false><#d7b486>Мир и перемещение ›",
            "settings-social-tooltip" to "<italic:false><#e8dfd2>Канал чата, уведомления и запросы телепортации.",
            "settings-social-label" to "<italic:false><#d7b486>Общение ›",
            "settings-interface-tooltip" to "<italic:false><#e8dfd2>Информационная панель и список игроков.<newline>Частицы, ресурспак и полоса автототема.",
            "settings-interface-label" to "<italic:false><#d7b486>Интерфейс ›",
            "settings-controls-tooltip" to "<italic:false><#e8dfd2>Горячая клавиша и поведение Escape.<newline>Редактирование табличек и посадка на ступеньки.",
            "settings-controls-label" to "<italic:false><#d7b486>Управление ›",
            "settings-world-back-label" to "<#aaa49a>‹ Назад",
            "settings-world-body" to "<italic:false><#aaa49a>Настройки / Мир и перемещение<newline><italic:false><#e8dfd2>Тропинки, полёт и взаимодействие с территориями.",
            "settings-world-title" to "<italic:false><#9bd48d>Мир и перемещение",
            "settings-social-back-label" to "<#aaa49a>‹ Назад",
            "settings-social-body" to "<italic:false><#aaa49a>Настройки / Общение<newline><italic:false><#e8dfd2>Кто вас слышит и какие сообщения вы получаете.",
            "settings-social-title" to "<italic:false><#f3a2c9>Общение",
            "settings-interface-back-label" to "<#aaa49a>‹ Назад",
            "settings-interface-body" to "<italic:false><#aaa49a>Настройки / Интерфейс<newline><italic:false><#e8dfd2>Информация на экране и визуальные эффекты.",
            "settings-interface-title" to "<italic:false><#86dcf1>Интерфейс",
            "settings-controls-back-label" to "<#aaa49a>‹ Назад",
            "settings-controls-body" to "<italic:false><#aaa49a>Настройки / Управление<newline><italic:false><#e8dfd2>Выберите привычные клавиши и действия.",
            "settings-controls-title" to "<italic:false><#f3a2c9>Управление",
            "legacy-action-flight-recharge-tooltip" to "<#e6fff3>Меню ручного пополнения запаса полёта.<newline><#c9c3ba>В нём можно выбрать опыт или игровые деньги<newline>и посмотреть стоимость доступного количества.<newline>Покупка заряда выполняется в этом меню.<newline><newline><#d7b486>Нажмите, чтобы открыть пополнение.",
            "legacy-action-flight-toggle-tooltip" to "<#e6fff3>Включить или выключить режим полёта за заряд.<newline><#c9c3ba>Для взлёта дважды нажмите прыжок.<newline>Нужны доступ к полёту и оставшийся заряд.<newline>Эта кнопка не выбирает способ подзарядки.<newline><newline><#d7b486>Нажмите, чтобы переключить режим полёта.",
            "legacy-action-flight-off-tooltip" to "<#e6fff3>Отключить автоматическую покупку заряда.<newline><#c9c3ba>Опыт и деньги перестанут тратиться<newline>на автопополнение. Накопленный заряд сохранится,<newline>и его можно будет использовать для полёта.<newline><newline><#d7b486>Нажмите, чтобы выключить автоподзарядку.",
            "legacy-action-flight-money-tooltip" to "<#e6fff3>Автоматически пополнять заряд за игровые деньги.<newline><#c9c3ba>Когда запас снизится, деньги будут списываться<newline>с вашего баланса без отдельного нажатия.<newline>Автопополнение за опыт будет выключено.<newline><newline><#d7b486>Нажмите, чтобы выбрать оплату деньгами.",
            "legacy-action-flight-exp-tooltip" to "<#e6fff3>Автоматически пополнять заряд за очки опыта.<newline><#c9c3ba>Когда запас снизится, опыт будет списываться<newline>без отдельного нажатия. Это очки, а не уровни.<newline>Автопополнение за деньги будет выключено.<newline><newline><#d7b486>Нажмите, чтобы выбрать оплату опытом.",
            "flight-body-start" to "<#f4bd6a>Как взлететь<newline><#e6fff3>Включите режим кнопкой «Переключить полёт», затем дважды нажмите прыжок. Нужны доступ к полёту и запас заряда. Настройка подзарядки сама по себе их не выдаёт.",
            "flight-body-recharge" to "<#f4bd6a>Автоподзарядка<newline><#e6fff3>При низком запасе заряд пополняется за выбранный ресурс: очки опыта или игровые деньги. Ресурс списывается автоматически. Режим «выкл» отключает только автопополнение.",
            "flight-body-how" to "<#f4bd6a>Как работает полёт<newline><#e6fff3>Это полёт с запасом заряда: он расходуется, пока вы летите или зависаете в воздухе. Остаток показывает полоса вверху экрана.",
            "setting-trails-off-tooltip" to "<#e6fff3>Ваши шаги участвуют в создании тропинок.<newline><#c9c3ba>Повторные проходы меняют подходящую землю<newline>и постепенно прокладывают маршрут.<newline>Выключение не убирает уже созданные тропы.<newline><newline><#d7b486>Нажмите, чтобы больше не протаптывать землю.",
            "setting-trails-on-tooltip" to "<#e6fff3>Повторные проходы постепенно протаптывают землю.<newline><#c9c3ba>Подходящие блоки меняются по стадиям,<newline>и на часто используемом маршруте появляется тропа.<newline><newline><#d7b486>Нажмите, чтобы ваши шаги создавали тропинки.",
            "setting-particles-tooltip" to "<#e6fff3>Видимость эффектов PlayerParticles.<newline><#c9c3ba>Отключите их, если частицы отвлекают,<newline>или включите, чтобы снова видеть эффекты.<newline>Настройка меняет их отображение для вас.<newline><newline><#d7b486>Нажмите, чтобы показать или скрыть частицы.",
            "setting-chat-local-tooltip" to "<#e6fff3>Локальный чат для общения поблизости.<newline><#c9c3ba>Ваши сообщения увидят игроки рядом.<newline>Подходит для разговора в одном месте.<newline><newline><#d7b486>Нажмите, чтобы писать в локальный чат.",
            "setting-chat-global-tooltip" to "<#e6fff3>Глобальный чат для общего общения.<newline><#c9c3ba>Сообщения отправляются в общий канал,<newline>даже если собеседник далеко от вас.<newline><newline><#d7b486>Нажмите, чтобы писать в глобальный чат.",
            "legacy-settings-portal-for-other-tooltip" to "<#e6fff3>Доступ других игроков к вашим порталам.<newline><#c9c3ba>Включено — разрешаете гостям использовать<newline>ваши порталы. Выключено — закрываете доступ.<newline>У гостя также должны быть включены чужие порталы.<newline><newline><#d7b486>Нажмите, чтобы переключить разрешение.",
            "legacy-settings-portal-by-other-tooltip" to "<#e6fff3>Использование порталов других игроков.<newline><#c9c3ba>Включено — вы разрешаете перемещать себя<newline>через чужие порталы, если владелец их открыл.<newline>Выключено — такие переходы запрещены.<newline><newline><#d7b486>Нажмите, чтобы переключить разрешение.",
            "legacy-settings-shortcut" to "<#d7b486>Shift + F: <state><#d7b486> ›",
            "legacy-settings-shortcut-tooltip" to "<#e6fff3>Выберите действие для Shift + F.<newline><#c9c3ba>Если вы сменили клавиши управления: приседание + смена рук.<newline>Выбор сохраняется между серверами. Обычная F не меняется.",
            "legacy-settings-escape" to "<#d7b486>Escape: <state><#d7b486> ›",
            "legacy-settings-escape-tooltip" to "<#e6fff3>Закрыть все меню или вернуться на предыдущий экран.<newline><#c9c3ba>По умолчанию — закрыть всё. Кнопка «Назад» доступна в обоих режимах.",
            "setting-selected" to "<#9cdb67>✔ ",
            "shortcut-unavailable" to "<#ff6b61>Назначенное действие сейчас недоступно. Выберите другое в настройках меню.",
            "escape-state-close" to "закрыть всё",
            "escape-state-back" to "назад",
            "legacy-action-escape-close" to "<#d7b486>Закрыть все меню",
            "legacy-action-escape-close-tooltip" to "<#e6fff3>Escape сразу возвращает в игру.<newline><#c9c3ba>Режим по умолчанию.",
            "legacy-action-escape-back" to "<#d7b486>Вернуться назад",
            "legacy-action-escape-back-tooltip" to "<#e6fff3>Escape выполняет действие кнопки «Назад».<newline><#c9c3ba>В главном меню — закрывает меню.",
            "shortcut-state-main" to "главное меню",
            "legacy-action-shortcut-main" to "<#d7b486>Главное меню",
            "legacy-action-shortcut-main-tooltip" to "<#e6fff3>Открыть главное меню сервера. Назначение по умолчанию.",
            "shortcut-state-mount" to "любимый маунт",
            "legacy-action-shortcut-mount" to "<#d7b486>Любимый маунт",
            "legacy-action-shortcut-mount-tooltip" to "<#e6fff3>Призвать выбранного любимого маунта. Выберите его заранее в /mount.",
            "shortcut-state-travel" to "телепортация и дома",
            "legacy-action-shortcut-travel" to "<#d7b486>Телепортация и дома",
            "legacy-action-shortcut-travel-tooltip" to "<#e6fff3>Открыть дома и доступные точки путешествий.",
            "shortcut-state-favorites" to "избранное",
            "legacy-action-shortcut-favorites" to "<#d7b486>Избранное",
            "legacy-action-shortcut-favorites-tooltip" to "<#e6fff3>Открыть закреплённые и недавно использованные действия.",
            "shortcut-state-settings" to "настройки",
            "legacy-action-shortcut-settings" to "<#d7b486>Настройки",
